window.LuminaSettings=async({root,api,L,e,message})=>{
 const field=(name,label,type='text')=>`<label class="field">${label}<input name="${name}" type="${type}"></label>`,flag=(name,label)=>`<label class="check-label"><input type="checkbox" name="${name}">${label}</label>`;
 let tab=typeof location!=='undefined'&&new URLSearchParams(location.search).get('section')==='environment'?'environment':'billing';async function draw(){const billing=await api('billing');root.innerHTML=`<nav class="settings-tabs" aria-label="${L('Settings sections','Rubriques des paramètres')}">${[['environment',L('Environment Mode','Mode de l’environnement')],['billing',L('Billing & invoices','Facturation et factures')],['rates',L('Exchange rates','Taux de change')],['email',L('Email delivery','Envoi des courriels')],['advanced',L('Advanced','Avancé')]].map(([key,text])=>'<button type="button" data-settings-tab="'+key+'" aria-selected="'+(tab===key)+'">'+text+'</button>').join('')}</nav><div data-settings-panel></div>`;root.querySelectorAll('[data-settings-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.settingsTab;draw().catch(message);});const panel=root.querySelector('[data-settings-panel]'),$=s=>root.querySelector(s);
 if(tab==='environment'){const state=await api('environment');panel.innerHTML=`<section class="commerce-box"><header class="environment-heading"><h2>${L('Environment Mode','Mode de l’environnement')}</h2><span class="environment-badge ${state.mode}">${state.mode.toUpperCase()}</span></header><label class="environment-toggle"><span>${L('Enable Test Mode','Activer le mode test')}</span><input type="checkbox" role="switch" data-test-mode ${state.mode==='test'?'checked':''}></label><p>${state.mode==='test'?L('Public checkout uses simulated payments only. No real money or emails are requested.','Le paiement public utilise uniquement des simulations. Aucun argent réel ni courriel n’est demandé.'):L('Public checkout uses live payments only when all receiving-account and billing requirements are satisfied.','Le paiement public utilise les paiements réels uniquement lorsque les comptes et la facturation sont conformes.')}</p>${!state.livePaymentReady?'<p class="simulation-banner">'+L('Live payment collection is blocked until billing and receiving-account readiness checks pass.','Les paiements réels restent bloqués tant que la facturation et les comptes ne sont pas conformes.')+'</p>':''}<p class="environment-meta">${L('Last changed','Dernière modification')}: ${state.lastChangedAt?e(new Date(state.lastChangedAt).toLocaleString()):L('Not changed','Aucune modification')} · ${e(state.lastChangedBy||'')}</p><p data-mode-status role="status"></p></section><section class="commerce-box"><h2>${L('Mode change history','Historique des changements')}</h2>${state.history.length?'<ul class="environment-history">'+state.history.map(h=>'<li><strong>'+e(h.from.toUpperCase())+' → '+e(h.to.toUpperCase())+'</strong><span>'+e(h.actor)+'</span><time>'+e(new Date(h.changedAt).toLocaleString())+'</time></li>').join('')+'</ul>':'<p>'+L('No mode changes yet.','Aucun changement de mode.')+'</p>'}</section>`;const toggle=$('[data-test-mode]');toggle.onchange=()=>{const next=toggle.checked?'test':'live',dialog=document.createElement('dialog');dialog.className='admin-dialog';dialog.setAttribute('aria-label',L('Confirm environment change','Confirmer le changement de mode'));dialog.innerHTML='<h2>'+L('Switch to ','Passer au mode ')+next.toUpperCase()+'?</h2><p>'+L('Existing orders keep their original mode. No records are deleted or converted.','Les commandes gardent leur mode d’origine. Aucune donnée n’est supprimée ou convertie.')+'</p><p>'+L(next==='test'?'Public checkout will use non-payable simulated instructions. Real payment and activation emails will stop.':'Live collection remains blocked unless all payment readiness checks pass.',next==='test'?'Le paiement public affichera des instructions simulées non payables. Les courriels de paiement et d’activation seront bloqués.':'Les paiements réels restent bloqués tant que toutes les exigences ne sont pas satisfaites.')+'</p><p data-mode-error role="alert"></p><div class="actions"><button class="btn" data-mode-cancel>'+L('Cancel','Annuler')+'</button><button class="btn primary" data-mode-confirm>'+L('Confirm switch','Confirmer le changement')+'</button></div>';panel.append(dialog);toggle.disabled=true;dialog.addEventListener('close',()=>{toggle.checked=state.mode==='test';toggle.disabled=false;dialog.remove();});dialog.querySelector('[data-mode-cancel]').onclick=()=>dialog.close();const requestId=crypto.randomUUID()+crypto.randomUUID();dialog.querySelector('[data-mode-confirm]').onclick=async event=>{const button=event.currentTarget;button.disabled=true;dialog.querySelector('[data-mode-cancel]').disabled=true;try{const changed=await api('environment',{mode:next,expectedRevision:state.revision,confirmation:next==='test'?'SWITCH TO TEST':'SWITCH TO LIVE',requestId});try{localStorage.setItem('lumina:environment-changed',JSON.stringify({mode:changed.mode,revision:changed.revision,at:Date.now()}));}catch{}sessionStorage.setItem('lumina:mode-result',L('Environment mode updated.','Mode de l’environnement mis à jour.'));location.href=location.pathname+'?section=environment';}catch(error){dialog.querySelector('[data-mode-error]').textContent=error.message;button.disabled=false;dialog.querySelector('[data-mode-cancel]').disabled=false;}};dialog.addEventListener('cancel',event=>{if(dialog.querySelector('[data-mode-confirm]').disabled)event.preventDefault();});dialog.showModal();};try{const result=sessionStorage.getItem('lumina:mode-result');if(result){$('[data-mode-status]').textContent=result;sessionStorage.removeItem('lumina:mode-result');}}catch{}
 }else if(tab==='billing'){panel.innerHTML=`<section class="commerce-box"><h2>${L('Billing and invoice requirements','Facturation et exigences des factures')}</h2><p><strong>Lumina Stream</strong> · ${L('Public brand. Legal seller details below stay private except on authorized documents. A configured 0% rate is not an exemption declaration.','Marque publique. Les données légales restent privées sauf dans les documents autorisés. Un taux de 0 % ne constitue pas une déclaration d’exonération.')}</p><form data-billing><div class="settings-form-grid">${field('sellerName',L('Legal seller name','Nom légal du vendeur'))}${field('sellerAddress',L('Legal address','Adresse légale'))}${field('sellerEmail',L('Seller email','Courriel du vendeur'),'email')}${field('taxNumber',L('Tax / registration identifier, if required','Identifiant fiscal / d’inscription, si requis'))}</div>${flag('taxConfigured',L('I explicitly configured the applicable tax rate','J’ai explicitement configuré le taux applicable'))}${field('taxLabel',L('Tax label','Libellé de taxe'))}${field('taxRate',L('Tax rate (%)','Taux (%)'),'number')}<details><summary>${L('Final invoice requirements','Exigences des factures définitives')}</summary>${flag('taxNumberRequired',L('Tax identifier required on final invoices','Identifiant fiscal requis sur les factures définitives'))}${flag('legalInformationVerified',L('I verified all legally required invoice information','J’ai vérifié toutes les mentions légales requises'))}${flag('finalInvoicesEnabled',L('Allow final tax invoices only when requirements are satisfied','Autoriser les factures fiscales définitives seulement si les exigences sont satisfaites'))}</details><button class="btn primary">${L('Save billing configuration','Enregistrer la facturation')}</button><p data-billing-status role="status"></p></form></section>`;
  const form=$('[data-billing]');for(const [name,value]of Object.entries({sellerName:billing.seller.name,sellerAddress:billing.seller.address,sellerEmail:billing.seller.email,taxNumber:billing.seller.taxNumber,taxLabel:billing.tax.label,taxRate:billing.tax.rateBps/100}))form.elements[name].value=value||value===0?value:'';
  form.elements.taxRate.min=0;form.elements.taxRate.max=30;form.elements.taxRate.step='.01';form.elements.taxConfigured.checked=billing.tax.configured;form.elements.taxNumberRequired.checked=billing.billing?.requiredFields?.includes('taxNumber')||false;for(const name of ['legalInformationVerified','finalInvoicesEnabled'])form.elements[name].checked=billing.billing?.[name]||false;
  form.onsubmit=async event=>{event.preventDefault();const button=event.submitter;button.disabled=true;try{const value=n=>form.elements[n].value;await api('billing',{seller:{name:value('sellerName'),address:value('sellerAddress'),email:value('sellerEmail'),taxNumber:value('taxNumber')},tax:{configured:form.elements.taxConfigured.checked,rateBps:Math.round(Number(value('taxRate'))*100),label:value('taxLabel')},billing:{legalInformationVerified:form.elements.legalInformationVerified.checked,finalInvoicesEnabled:form.elements.finalInvoicesEnabled.checked,requiredFields:['name','address','email',...(form.elements.taxNumberRequired.checked?['taxNumber']:[])]}});$('[data-billing-status]').textContent=L('Saved','Enregistré');}catch(error){$('[data-billing-status]').textContent=error.message;}finally{button.disabled=false;}};
 }else if(tab==='rates'){panel.innerHTML='<p>'+L('Loading current rates…','Chargement des cours…')+'</p>';const data=await api('exchange-rates');panel.innerHTML=`<div class="rate-grid">${Object.entries(data.rates).map(([token,r])=>'<section class="commerce-box"><h2>'+token+' / CAD</h2><strong>'+(r.error?L('Unavailable','Indisponible'):e(r.cadPerToken)+' CAD')+'</strong><p>'+e(r.source||r.error)+'</p><p>'+L('Fetched','Récupéré')+': '+e(r.quotedAt||'')+'<br>'+L('Expires','Expire')+': '+e(r.expiresAt||'')+'</p></section>').join('')}</div><p>${L('Rates refresh automatically every five minutes when used. No stale rates are used if the provider fails.','Les cours sont actualisés automatiquement toutes les cinq minutes lors de leur utilisation. Aucun cours expiré n’est utilisé si le fournisseur échoue.')}</p>`;
 }else{const s=await api('settings');if(tab==='email'){panel.innerHTML=`<section class="commerce-box"><h2>${L('Email delivery','Envoi des courriels')}</h2><form data-email-settings>${flag('enabled',L('Enable email delivery','Activer les courriels'))}${field('from',L('Verified sender address','Adresse d’expéditeur vérifiée'))}<p>${L('Requires a configured provider secret and verified sender domain.','Nécessite le secret du fournisseur et un domaine d’expéditeur vérifié.')}</p><button class="btn primary">${L('Save','Enregistrer')}</button></form></section>`;const form=$('[data-email-settings]');form.elements.enabled.checked=s.email.enabled;form.elements.from.value=s.email.from;form.onsubmit=async ev=>{ev.preventDefault();try{await api('settings',{...s,email:{enabled:form.elements.enabled.checked,from:form.elements.from.value}});message(L('Saved','Enregistré'));}catch(error){message(error);}};}else{panel.innerHTML=`<details><summary>${L('Advanced technical configuration','Configuration technique avancée')}</summary><form data-technical><textarea rows="25" name="json" spellcheck="false">${e(JSON.stringify(s,null,2))}</textarea><button class="btn">${L('Validate and save','Valider et enregistrer')}</button></form></details>`;root.querySelector('[data-technical]').onsubmit=async ev=>{ev.preventDefault();try{await api('settings',JSON.parse(ev.target.elements.json.value));message(L('Saved','Enregistré'));}catch(error){message(error);}};}}
 }await draw();
};
